        <details class="evaluation-snapshot"><summary>Recorded inputs and policy snapshots</summary><h3 class="records-section-title">Inputs at evaluation time</h3><x-evaluation-snapshot :value="$run->input_snapshot" /><h3 class="records-section-title mt-4">Rules at evaluation time</h3><x-evaluation-snapshot :value="$run->rule_snapshot" /><details><summary>Original snapshot JSON</summary><pre class="evaluation-raw-snapshot">{{ json_encode(['inputs' => $run->input_snapshot, 'rules' => $run->rule_snapshot], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES) }}</pre></details></details>
